import csv,json,pathlib,re
p=pathlib.Path(__file__).resolve().parent;checks=[]
def check(n,b):assert b,n;checks.append(n)
s=json.loads((p/'search-log.json').read_text());z=json.loads((p/'summary.json').read_text());pub=[json.loads(l)for l in(p/'pubmed-screening.jsonl').read_text().splitlines()];reg=[json.loads(l)for l in(p/'registry-evidence.jsonl').read_text().splitlines()]
check('date',s['date']=='2026-11-02');check('ordered times',s['prior_core_end_utc']<s['started_utc']<s['completed_utc']);check('eight query families',len(s['pubmed']['queries'])==8);check('32 unique records',len(pub)==len({x['pmid']for x in pub})==32);check('35 occurrences',sum(x.get('count',0)for x in s['pubmed']['queries'])==35);check('queries/fetch union',set().union(*(set(q.get('ids',[]))for q in s['pubmed']['queries']))=={x['pmid']for x in pub});check('complete screens',all('Pending'not in x['screening_decision']for x in pub));check('no abstracts',all('abstract'not in x for x in pub));check('old online dates',all('-'.join(d[k]for k in ['Year','Month','Day'])<'2026-11-01'for x in pub for d in x['article_dates']));check('41 successful requests',len(s['retrieval_requests'])==41 and all(x.get('status')==200 and 'error'not in x for x in s['retrieval_requests']));check('no worker errors',not s.get('worker_errors'))
for x in s['preprints']:
 check(x['server']+' pagination',x['pagination_complete_for_observed_response']);check(x['server']+' stable totals',len(x['reported_totals'])==1);check(x['server']+' unique index',len({(a['doi'],a['version'])for a in x['version_index']})==x['unique_doi_versions']);check(x['server']+' no matches',not x['matches'])
 for term,expected in [('Tourette syndrome',True),('persistent motor tics',True),('statistics',False)]:check(x['server']+' '+term,bool(re.search(x['screen_regex'],term,re.I))==expected)
check('676 records',sum(x['unique_doi_versions']for x in s['preprints'])==676);check('five registry comparisons',len(reg)==5);check('no results',all(x['hasResults']==False for x in reg));check('selected fields unchanged',all(not x['selected_field_changes']for x in reg));check('four empty queries',len(s['registry'])==4 and all(x['response']['totalCount']==0 for x in s['registry']));check('no truncated queries',all(not x['response']['nextPageToken']for x in s['registry']));check('summary consistent',z['pubmed_unique_records']==len(pub)and z['api_request_errors']==0)
(p/'validation.json').write_text(json.dumps({'passed':len(checks),'checks':checks,'limitations':'Software/data consistency, not independent clinical review.'},indent=2)+'\n');print(len(checks),'checks passed')
